const FILES = {
 '/': ['text/html; charset=utf-8',''],
 '/index.html': ['text/html; charset=utf-8',''],
 '/admin.html': ['text/html; charset=utf-8',''],
 '/sw.js': ['application/javascript; charset=utf-8',''],
 '/admin.webmanifest': ['application/manifest+json',''],
 '/ativar.html': ['text/html; charset=utf-8',''],
 '/logo-app.png': ['image/png',''],
 '/icon-192.png': ['image/png',''],
 '/icon-512.png': ['image/png',''],
 '/Avalanche.jpeg': ['image/jpeg',''],
 '/cachoro quente na chapa.jpeg': ['image/jpeg',''],
 '/calafrango.jpeg': ['image/jpeg',''],
 '/coca-cola 2l.jpg': ['image/jpeg',''],
 '/coca-cola lata.jpg': ['image/jpeg',''],
 '/guarana 1l.jpg': ['image/jpeg',''],
 '/gurana lata.jpg': ['image/jpeg',''],
 '/icon-180.png': ['image/png',''],
 '/icon.svg': ['image/svg+xml',''],
 '/xbacon.jpg': ['image/jpeg',''],
 '/xburguer.jpeg': ['image/jpeg',''],
 '/xtudo.jpeg': ['image/jpeg',''],
};

export default {
  async fetch(req) {
    const u = new URL(req.url);
    let p = u.pathname;
    try { p = decodeURIComponent(p); } catch (e) {}
    if (p === '/' || p === '') p = '/index.html';
    const f = FILES[p];
    if (!f) return new Response('Não encontrado', { status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
    const bytes = Uint8Array.from(atob(f[1]), c => c.charCodeAt(0));
    return new Response(bytes, { headers: { 'Content-Type': f[0], 'Cache-Control': 'no-cache', 'Service-Worker-Allowed': '/' } });
  }
};
